1	//! Epic status as a read-only rollup of its children.
2	//!
3	//! An EPIC's status is NOT a manually-set field — it is a projection of the
4	//! statuses of its children (the same child subtree `aida graph --tree` rolls
5	//! up). Manual epic status edits drift from reality in both directions: a
6	//! childless epic can read In Progress (false "active"), and an epic whose
7	//! children are shipping can read Draft (false "not started"). This module is
8	//! the single source of the derived status; every display surface (`aida list`
9	//! via the cache projection, `aida show`, `aida why`, `aida status`) routes
10	//! through it so the cache-backed and full-store paths agree, and the edit
11	//! guard in `aida-cli` rejects manual epic status sets so the field can't drift.
12	//!
13	//! The derivation reuses [`graph_walk::child_status_rollup`] — the SAME walk +
14	//! rollup the `--tree` render prints — so the derived status is always
15	//! consistent with the rollup numbers an operator sees.
16	//!
17	//! trace:BUG-626 | ai:claude
18	
19	use crate::graph_walk::{child_status_rollup, StatusRollup};
20	use crate::models::{RequirementStatus, RequirementType, RequirementsStore};
21	use uuid::Uuid;
22	
23	/// Derive an epic's effective status from the rollup of its children.
24	///
25	/// Precedence (evaluated top to bottom; `total` is the child count):
26	///
27	/// 1. **No children** (`total == 0`) -> `Draft` — nothing has started; the epic
28	///    still needs decomposition. (`aida why` already says "decompose — an epic
29	///    with no children yet"; this makes the status agree.)
30	/// 2. **All non-Rejected children Completed** -> `Completed`. A Rejected child
31	///    is RESOLVED, not open — it can never transition again, so it must not
32	///    hold the epic in a perpetual "in progress" it can't leave (the BUG-764
33	///    stuck state: an epic whose last open child completed via the `aida pull`
34	///    auto-bump but that also carried a rejected child read In Progress
35	///    forever).
36	/// 3. **All non-Rejected children Done or Completed** (some on a branch, not
37	///    all merged) -> `Done`.
38	/// 4. **At least one child In Progress, OR a mix of done-and-not-done work** ->
39	///    `InProgress` — the epic is actively moving.
40	/// 5. **At least one child shelved (NeedsAttention) and none In Progress** ->
41	///    `NeedsAttention` — a child is blocked / needs a decision. (There is no
42	///    `Blocked` status variant; `NeedsAttention` is its closest analogue.)
43	/// 6. **Only remaining (Draft/Approved/Planned) children, none in progress** ->
44	///    `Draft` — queued but not started.
45	/// 7. **Only Rejected children** (every other bucket empty) -> `None`: we do not
46	///    auto-reject an epic. The caller keeps the epic's stored status so a human
47	///    can make that call (and `--force` recovery still works).
48	///
49	/// Returns `None` only in case (7); every other case yields a derived status.
50	// trace:BUG-626 | ai:claude
51	pub fn derive_epic_status_from_rollup(r: &StatusRollup) -> Option<RequirementStatus> {
52	    // (1) Childless epic — nothing started.
53	    if r.total == 0 {
54	        return Some(RequirementStatus::Draft);
55	    }
56	
57	    // Rejected children are resolved (terminal), not open: exclude them from
58	    // the finished-vs-open denominator so an epic with zero OPEN children can
59	    // reach Completed/Done. Before this, a completed+rejected mix fell through
60	    // to the `any_finished` arm and derived InProgress forever — no child
61	    // transition could ever move it again. trace:BUG-764 | ai:claude
62	    let unrejected = r.total - r.rejected;
63	
64	    // (2) Every non-rejected child Completed.
65	    if unrejected > 0 && r.completed == unrejected {
66	        return Some(RequirementStatus::Completed);
67	    }
68	
69	    // (3) Every non-rejected child Done or Completed — work finished on
70	    // branches, not all merged yet.
71	    if unrejected > 0 && r.done + r.completed == unrejected {
72	        return Some(RequirementStatus::Done);
73	    }
74	
75	    // (4) Actively moving: a child is in progress, OR some work is already
76	    // done/completed while other children are not (a partially-shipped epic is
77	    // unambiguously "in progress").
78	    let any_finished = r.done + r.completed > 0;
79	    if r.in_progress > 0 || any_finished {
80	        return Some(RequirementStatus::InProgress);
81	    }
82	
83	    // From here: no in-progress and nothing finished — the epic hasn't started.
84	
85	    // (5) A child is shelved and nothing is moving — surface the stall.
86	    if r.shelved > 0 {
87	        return Some(RequirementStatus::NeedsAttention);
88	    }
89	
90	    // (6) Only queued work remains (Draft/Approved/Planned children).
91	    if r.remaining > 0 {
92	        return Some(RequirementStatus::Draft);
93	    }
94	
95	    // (7) Only Rejected children left (total > 0 but every non-rejected bucket is
96	    // empty). Don't auto-reject the epic; let the caller keep the stored status.
97	    None
98	}
99	
100	/// Derive an epic's effective status from the live store. Returns the rollup
101	/// status for an epic with the precedence above. Returns `None` when:
102	/// - `epic_id` doesn't resolve, or the resolved spec is not an Epic (callers
103	///   should only display the stored status for non-epics), or
104	/// - the epic's only children are Rejected (case 7 above — keep stored status).
105	// trace:BUG-626 | ai:claude
106	pub fn derive_epic_status(store: &RequirementsStore, epic_id: Uuid) -> Option<RequirementStatus> {
107	    let req = store.get_requirement_by_id(&epic_id)?;
108	    if req.req_type != RequirementType::Epic {
109	        return None;
110	    }
111	    let rollup = child_status_rollup(store, epic_id);
112	    derive_epic_status_from_rollup(&rollup)
113	}
